REVOKE INSERT,UPDATE,DELETE ON public.financeiro FROM authenticated;
CREATE OR REPLACE FUNCTION public.aprovar_comprovante(_id uuid,_nota uuid,_data_entrega timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c comprovantes;n notas_fiscais;e_id uuid;nome text; BEGIN IF auth.uid() IS NULL OR NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; SELECT * INTO c FROM comprovantes WHERE id=_id FOR UPDATE; IF NOT FOUND OR c.status IN ('aprovado','rejeitado') THEN RAISE EXCEPTION 'Comprovante inexistente ou já revisado'; END IF; IF c.tipo_documento<>'canhoto' THEN RAISE EXCEPTION 'Somente canhoto validado pode gerar entrega'; END IF; SELECT * INTO n FROM notas_fiscais WHERE id=_nota FOR UPDATE; IF NOT FOUND OR n.carga_id IS NULL OR NOT EXISTS(SELECT 1 FROM cargas WHERE id=n.carga_id AND motorista_id=c.motorista_id) THEN RAISE EXCEPTION 'Nota não pertence a este motorista'; END IF; SELECT p.nome INTO nome FROM profiles p WHERE p.id=auth.uid(); SELECT id INTO e_id FROM entregas WHERE nota_id=_nota AND resultado='entregue' ORDER BY created_at DESC LIMIT 1; IF e_id IS NULL THEN INSERT INTO entregas(nota_id,carga_id,data_evento,resultado,observacao,registrado_por) VALUES(_nota,n.carga_id,coalesce(_data_entrega,c.capturado_em),'entregue','Comprovante aprovado pelo escritório',auth.uid()) RETURNING id INTO e_id;END IF; UPDATE comprovantes SET status='aprovado',nota_id=_nota,carga_id=n.carga_id,data_entrega=coalesce(_data_entrega,c.capturado_em),revisado_por=auth.uid(),revisado_por_nome=nome,revisado_em=now(),entrega_id=e_id WHERE id=_id; UPDATE notas_fiscais SET status='entregue' WHERE id=_nota AND status<>'entregue'; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('nota',_nota,'comprovante_aprovado','Canhoto aprovado; NF '||n.numero||' entregue',auth.uid());RETURN e_id;END $$;
CREATE OR REPLACE FUNCTION public.tg_note_requires_approved_proof() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='entregue' AND OLD.status<>'entregue' AND NOT EXISTS(SELECT 1 FROM comprovantes WHERE nota_id=NEW.id AND status='aprovado' AND tipo_documento='canhoto') THEN RAISE EXCEPTION 'Entrega exige canhoto validado pelo escritório';END IF; RETURN NEW;END $$;
CREATE TRIGGER note_requires_approved_proof BEFORE UPDATE OF status ON public.notas_fiscais FOR EACH ROW EXECUTE FUNCTION public.tg_note_requires_approved_proof();